mapper.select:
select SUM(t.prize) as prize,SUM(t.cost) as cost,t.anchor,t.update_time as updateTime,u.nick_name as nickName from (
select prize,cost,anchor,update_time from ${dbLive}.lottery_bet where status = '1'
 and anchor = #{id}
 and update_time >= #{startTime}
 and update_time <= #{endTime}
and anchor <> '-1'
UNION all
select prize,cost,anchor,update_time from ${dbLottery}.lottery_bet_view where status = '1'
 and anchor = #{id}
 and update_time >= #{startTime}
 and update_time <= #{endTime}
and anchor <> '-1') t left join ${dbLive}.live_user u on u.id = t.anchor

     and u.nick_name like concat(#{nickName}, '%')

GROUP BY t.anchor
